pairs = [
    ('import { createFileRoute, Outlet, redirect } from "@tanstack/react-router"\n',
     'import {\n  createFileRoute,\n  Outlet,\n  redirect,\n  useRouter,\n} from "@tanstack/react-router"\nimport { useEffect, useRef } from "react"\n'),
    ('import { isLoggedIn } from "@/hooks/useAuth"\n', 'import useAuth, { isLoggedIn } from "@/hooks/useAuth"\n'),
    ('''function Layout() {
  return (''', '''// The current user is refetched when the tab regains focus. If an admin changed
// their role meanwhile, re-run the route guards so a page they lost access to
// is left right away instead of on the next request that happens to get a 403.
function useGuardsFollowPermissions() {
  const { user } = useAuth()
  const router = useRouter()
  const permissions = user?.permissions.join(" ")
  const previous = useRef(permissions)

  useEffect(() => {
    if (previous.current !== undefined && permissions !== previous.current) {
      router.invalidate()
    }
    previous.current = permissions
  }, [permissions, router])
}

function Layout() {
  useGuardsFollowPermissions()

  return ('''),
]
